integrity_fields := {"checksum", "sha256", "md5", "hash", "digest", "signature", "sign", "gpg", "cosign", "content_digest", "checksum_sha256", "checksum_md5", "sha256sum", "md5sum", "sha1", "sha512", "gpg_key", "gpgcheck", "repo_gpgcheck", "verify", "pgp_key"}

url_fields := {"url", "source", "download_url", "package_url", "src", "uri", "address", "location", "path"}

verify_disable_values := {false, 0, "false", "no", "0", "disabled", "off"}

insecure_protocols := {"http://", "ftp://", "git::http://", "https?://", "ftp", "http", "git+http://"}

container_image_fields := {"image", "container_image", "container", "image_name"}

bypass_fields := {"skip_verify", "insecure_skip_verify", "validate_certs", "insecure", "verify_ssl", "ssl_verify", "gpgcheck", "repo_gpgcheck", "verify"}

check_values_for_integrity(val) {
    val.ir_type == "Hash"
    val.value[_].key.value == "args"
    walk(val.value[_].value, [_, n])
    n.ir_type == "String"
    integrity_fields[f]
    contains(lower(n.value), f)
}

check_values_for_integrity(val) {
    val.ir_type == "Array"
    val.value[_].ir_type == "String"
    integrity_fields[f]
    contains(lower(val.value[_].value), f)
}

check_values_for_integrity(val) {
    val.ir_type == "String"
    integrity_fields[f]
    contains(lower(val.value), f)
}

has_integrity_indicator(val) {
    check_values_for_integrity(val)
}

has_integrity_in_attrs(attrs) {
    attr := attrs[_]
    integrity_fields[lower(attr.name)]
    attr.value.ir_type != "Null"
    attr.value.ir_type != "Undef"
} else {
    attr := attrs[_]
    integrity_fields[lower(attr.name)]
