has_integrity_in_nested(node) {
    walk(node, [path, val])
    val.ir_type == "Hash"
    val.value[_]
    key_str := val.value[_].key.value
    integrity_fields[lower(key_str)]
    val.value[_].value.ir_type != "Null"
    val.value[_].value.ir_type != "Undef"
} else {
    walk(node, [path, val])
    val.ir_type == "Attribute"
    integrity_fields[lower(val.name)]
    val.value.ir_type != "Null"
    val.value.ir_type != "Undef"
}

has_disabled_verification(val) {
    val.ir_type == "Boolean"
    val.value == false
} else {
    val.ir_type == "Integer"
    val.value == 0
} else {
    val.ir_type == "String"
    verify_disable_values[lower(val.value)]
}

has_bypass_in_attrs(attrs) {
    attr := attrs[_]
    bypass_fields[lower(attr.name)]
    has_disabled_verification(attr.value)
}

has_insecure_protocol(val) {
    val.ir_type == "String"
    proto := insecure_protocols[_]
    startswith(lower(val.value), proto)
}

has_url_field_in_attrs(attrs) {
    attr := attrs[_]
    url_fields[lower(attr.name)]
    attr.value.ir_type == "String"
} else {
    attr := attrs[_]
    url_fields[lower(attr.name)]
    attr.value.ir_type == "Sum"
    walk(attr.value, [_, n])
    n.ir_type == "String"
    startswith(lower(n.value), "http")
}

has_remote_reference(node) {
    has_url_field_in_attrs(node.attributes)
} else {
