package glitch

import data.glitch_lib

integrity_fields := {"checksum", "sha256", "md5", "hash", "digest", "signature", "sign", "gpg", "cosign", "content_digest", "checksum_sha256", "checksum_md5", "sha256sum", "md5sum", "sha1", "sha512", "gpg_key", "gpgcheck", "repo_gpgcheck", "verify", "pgp_key"}

url_fields := {"url", "source", "download_url", "package_url", "src", "uri", "address", "location", "path"}

verify_disable_values := {false, 0, "false", "no", "0", "disabled", "off", "False", "NO", "DISABLED"}

insecure_protocols := {"http://", "ftp://", "git::http://", "git+http://", "http", "ftp"}

check_disable(val) {
    val.ir_type == "Boolean"
    val.value == false
}

check_disable(val) {
    val.ir_type == "Integer"
    val.value == 0
}

check_disable(val) {
    val.ir_type == "String"
    lower(val.value) == "false"
} else {
    val.ir_type == "String"
    lower(val.value) == "no"
} else {
    val.ir_type == "String"
    lower(val.value) == "0"
} else {
    val.ir_type == "String"
    lower(val.value) == "disabled"
}

has_url_remote_reference(node) {
    walk(node, [_, val])
    val.ir_type == "String"
    url := val.value
    startswith(lower(url), "http")
} else {
    walk(node, [_, val])
    val.ir_type == "String"
    url := val.value
    startswith(lower(url), "ftp")
} else {
    walk(node, [_, val])
    val.ir_type == "String"
    url := val.value
    startswith(lower(url), "git")
}

has_integrity_attr(node) {
    walk(node, [_, val])
    val.ir_type == "Attribute"
    integrity_fields[lower(val.name)]
    val.value.ir_type != "Null"
    val.value.ir_type != "Undef"
}

has_integrity_in_nested(node) {
    walk(node, [_, val])
    val.ir_type == "Hash"
    entry := val.value[_]
    integrity_fields[lower(entry.key.value)]
    entry.value.ir_type != "Null"
    entry.value.ir_type != "Undef"
}

has_bypass_disabled(node) {
    walk(node, [_, val])
    val.ir_type == "Attribute"
    lower(val.name) == "gpgcheck"
    check_disable(val.value)
}

has_bypass_disabled(node) {
    walk(node, [_, val])
    val.ir_type == "Attribute"
    lower(val.name) == "repo_gpgcheck"
    check_disable(val.value)
}

has_bypass_disabled(node) {
    walk(node, [_, val])
