    lower(val.name) == "validate_certs"
    check_disable(val.value)
}

has_bypass_disabled(node) {
    walk(node, [_, val])
    val.ir_type == "Attribute"
    lower(val.name) == "verify"
    check_disable(val.value)
}

has_bypass_disabled(node) {
    walk(node, [_, val])
    val.ir_type == "Attribute"
    lower(val.name) == "insecure"
    check_disable(val.value)
}

has_bypass_disabled(node) {
    walk(node, [_, val])
    val.ir_type == "Attribute"
    lower(val.name) == "skip_verify"
    check_disable(val.value)
}

has_bypass_disabled_nested(node) {
    walk(node, [_, val])
    val.ir_type == "Hash"
    entry := val.value[_]
    lower(entry.key.value) == "gpgcheck"
    check_disable(entry.value)
}

has_bypass_disabled_nested(node) {
    walk(node, [_, val])
    val.ir_type == "Hash"
    entry := val.value[_]
    lower(entry.key.value) == "repo_gpgcheck"
    check_disable(entry.value)
}

all_atomic_units_recursive(node) = units {
