        walk(node, [_, val])
        val.ir_type == "AtomicUnit"
        au := val
    }
}

all_variables_recursive(node) = vars {
    vars := {v |
        walk(node, [_, val])
        val.ir_type == "Variable"
        v := val
    }
}

